package com.travel.meomulkyung.itinerary.dto;
import java.time.*; import java.util.*;
public final class ItineraryResponses { private ItineraryResponses(){} public record Itinerary(Long itineraryId,String status,boolean bookmarked,Region region,String title,LocalDate startDate,LocalDate endDate,int nights,int generationVersion,List<Day> days,List<Warning> warnings){} public record Region(Long regionId,String regionName){} public record Day(int dayNumber,LocalDate date,Weather weather,List<Item> items){} public record Weather(boolean available,String condition,Integer minimumTemperature,Integer maximumTemperature){} public record Item(Long itemId,int sequence,String type,String title,Long placeId,Long festivalId,String imageUrl,String address,Double latitude,Double longitude,LocalDate eventStartDate,LocalDate eventEndDate,String reason,boolean replaceable){} public record Warning(String code,String message){} public record Bookmark(Long itineraryId,boolean bookmarked,LocalDateTime bookmarkedAt){} public record Replacement(Long itineraryId,Long replacedItemId,Item newItem,int generationVersion){} public record Completion(Long completedTripId,Long itineraryId,Region region,int stayHours,int partySize,long totalSpent,Stamp stamp,Contribution contribution,LocalDateTime completedAt){} public record Stamp(boolean awarded,boolean newlyAwarded,Long regionId,String regionName,int visitCount){} public record Contribution(Integer populationContributionDays,String calculationStatus,String calculationPolicyVersion){} public record WeatherDays(List<WeatherDay> days){} public record WeatherDay(LocalDate date,boolean available,String icon,Integer temp){} }
